    const missingDrainable = drainableClosed && quantumFaces && primaryTools && residualsNamedHonest ? 0 : 1
    const pairAll = has('mcp/all') && has('all/mcp') && soft('mcp', 'all') && soft('all', 'mcp')
    const meta = catalog.tools.find((t) => t.id === 'mcp-all')
